const candidate = r.states.items[chosen];
if (s.image_frame != 0 or !@import("cache_images.zig").diskSafe(candidate.tokens) or
    !@import("cache_images.zig").equal(&.{}, s.image_query orelse &.{}, @intCast(candidate.tokens.len))) return have;
const name = candidate.name;
const bytes = r.blankBytes(candidate.at);
if (bytes > s.budget or s.most == 0) return have;
const at = candidate.at;
if (!ready(s, at, bytes)) present(r, chosen) catch |err| return failed(before, at, err, have); // nothing goes to make room for a state whose file is gone

e.saved = read(r, i) catch |err| { // the read failed: the state is not read again in this process
    r.markUnreadable(name); // port note (af9777b49): the fork's unreadable mark beside upstream's retry path
    s.counts.disk_recalls_failed += 1;
    pc.note("imprint: reading {d} tokens back failed ({s}); the state is not read again here", .{ at, @errorName(err) });
    return failed(before, at, err, have);
};
